PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE agents (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, base_url TEXT NOT NULL, secret_cipher BLOB NOT NULL, version TEXT NOT NULL DEFAULT '', read_only INTEGER NOT NULL DEFAULT 0, last_heartbeat TEXT, last_sync TEXT, created_at TEXT NOT NULL);
CREATE TABLE containers (id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE CASCADE, docker_id TEXT NOT NULL, name TEXT NOT NULL, image TEXT NOT NULL, tag TEXT NOT NULL DEFAULT '', current_digest TEXT NOT NULL DEFAULT '', remote_digest TEXT NOT NULL DEFAULT '', update_available INTEGER NOT NULL DEFAULT 0, detection_method TEXT NOT NULL DEFAULT '', runtime_status TEXT NOT NULL, management_kind TEXT NOT NULL, compose_project TEXT NOT NULL DEFAULT '', compose_service TEXT NOT NULL DEFAULT '', compose_working_dir TEXT NOT NULL DEFAULT '', labels_json TEXT NOT NULL DEFAULT '{}', ignored INTEGER NOT NULL DEFAULT 0, protected INTEGER NOT NULL DEFAULT 0, sensitive INTEGER NOT NULL DEFAULT 0, manageable INTEGER NOT NULL DEFAULT 0, safety_reason TEXT NOT NULL DEFAULT '', last_sync TEXT NOT NULL, UNIQUE(agent_id, docker_id));
CREATE INDEX idx_containers_agent ON containers(agent_id);
CREATE TABLE image_snapshots (id INTEGER PRIMARY KEY AUTOINCREMENT, container_id TEXT NOT NULL REFERENCES containers(id) ON DELETE CASCADE, image TEXT NOT NULL, current_digest TEXT, remote_digest TEXT, update_available INTEGER NOT NULL, observed_at TEXT NOT NULL);
CREATE TABLE update_jobs (id TEXT PRIMARY KEY, agent_job_id TEXT NOT NULL DEFAULT '', agent_id TEXT NOT NULL REFERENCES agents(id), container_id TEXT REFERENCES containers(id), target_key TEXT NOT NULL, action TEXT NOT NULL, status TEXT NOT NULL, requested_by TEXT NOT NULL, correlation_id TEXT NOT NULL, dry_run_plan TEXT NOT NULL DEFAULT '', error TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, started_at TEXT, finished_at TEXT);
CREATE UNIQUE INDEX idx_jobs_active_target ON update_jobs(target_key) WHERE status IN ('queued','running');
CREATE TABLE update_events (id INTEGER PRIMARY KEY AUTOINCREMENT, job_id TEXT NOT NULL REFERENCES update_jobs(id) ON DELETE CASCADE, level TEXT NOT NULL, message TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX idx_events_job ON update_events(job_id, id);
CREATE TABLE ignore_rules (id INTEGER PRIMARY KEY AUTOINCREMENT, agent_id TEXT REFERENCES agents(id) ON DELETE CASCADE, pattern TEXT NOT NULL, kind TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE schedules (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, cron TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, selector_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE health_checks (id INTEGER PRIMARY KEY AUTOINCREMENT, agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE CASCADE, status TEXT NOT NULL, latency_ms INTEGER, detail TEXT NOT NULL DEFAULT '', checked_at TEXT NOT NULL);
